async function loadFeature(name: string): Promise<string> {
    // Haqiqiy loyihada: const module = await import(`./features/${name}.js`)
    const modules: Record<string, () => Promise<{ default: string }>> = {
        charts: async () => ({ default: "Grafiklar moduli yuklandi" }),
        editor: async () => ({ default: "Muharrir moduli yuklandi" }),
    }

    const loader = modules[name]
    if (!loader) return `"${name}" moduli topilmadi`

    const module = await loader()
    return module.default
